const CSS = `#eight-splash{position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;background:linear-gradient(168deg,#EFE5D7 0%,#EBE0D1 45%,#DCCAB5 100%);transition:opacity .5s ease,transform .5s ease;-webkit-user-select:none;user-select:none}
#eight-splash.es-out{opacity:0;transform:scale(1.03);pointer-events:none}
#eight-splash.es-skip{display:none}
#eight-splash .es-stage{display:flex;flex-direction:column;align-items:center;gap:clamp(14px,4.4vmin,34px);transform:translateY(-2%);opacity:0;animation:es-in .35s ease .05s forwards}
#eight-splash svg{display:block;width:100%;height:100%;overflow:visible}
#eight-splash .es-num{width:clamp(58px,17vmin,124px);aspect-ratio:0.625;
 -webkit-mask:url(data:image/png;base64,) no-repeat center/100% 100%;
 mask:url(data:image/png;base64,) no-repeat center/100% 100%}
#eight-splash .es-num path{stroke-dasharray:1;stroke-dashoffset:1;animation:es-draw 1.15s cubic-bezier(.42,.02,.36,1) 0.12s forwards}
#eight-splash .es-word{position:relative;width:clamp(112px,32vmin,232px);aspect-ratio:6.57}
#eight-splash .es-word span{position:absolute;top:0;height:100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:center;mask-position:center;-webkit-mask-size:100% 100%;mask-size:100% 100%}
#eight-splash .es-word path{stroke-dasharray:1;stroke-dashoffset:1;animation:es-draw 0.42s cubic-bezier(.45,0,.3,1) var(--d) forwards}
@keyframes es-draw{to{stroke-dashoffset:0}}
@keyframes es-in{to{opacity:1}}
@media (prefers-reduced-motion:reduce){#eight-splash path{animation:none!important;stroke-dashoffset:0}#eight-splash .es-stage{animation:none;opacity:1}}`;

