const JS = `(function(){var e=document.getElementById("eight-splash");if(!e)return;var app=matchMedia("(display-mode:standalone)").matches||navigator.standalone;var seen=false;try{seen=sessionStorage.getItem("es8")==="1"}catch(x){}if(seen){e.classList.add("es-skip");e.parentNode&&e.parentNode.removeChild(e);return}try{sessionStorage.setItem("es8","1")}catch(x){}var t=Date.now(),m=app?2300:1700,d=false;function h(){if(d)return;d=true;setTimeout(function(){e.classList.add("es-out");setTimeout(function(){e.parentNode&&e.parentNode.removeChild(e)},600)},Math.max(0,m-(Date.now()-t)))}if(document.readyState==="complete")h();else addEventListener("load",h);setTimeout(h,7000);window.EIGHT_SPLASH={hide:h}})();`;

export default function BootSplash() {
  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <div dangerouslySetInnerHTML={{ __html: MARKUP }} />
      <script dangerouslySetInnerHTML={{ __html: JS }} />
    </>
  );
}
